import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds half-cent ties to the even cent so invoices aren't biased upward", () => {
    expect(roundCents(100.5)).toBe(100);
    expect(roundCents(101.5)).toBe(102);
    expect(roundCents(0.5)).toBe(0);
  });

  it("rounds non-tie fractions to the nearest cent", () => {
    expect(roundCents(100.4)).toBe(100);
    expect(roundCents(100.6)).toBe(101);
    expect(roundCents(250)).toBe(250);
  });

  it("applies half-to-even symmetrically to credits and refunds", () => {
    expect(roundCents(-2.5)).toBe(-2);
    expect(roundCents(-3.5)).toBe(-4);
    expect(roundCents(-2.6)).toBe(-3);
  });

  it("treats floating-point drift around a half cent as a tie", () => {
    expect(roundCents(0.1 * 25)).toBe(2); // 2.5000000000000004
    expect(roundCents(1.15 * 10)).toBe(12); // 11.499999999999998
  });
});

